def approx_less_than(x, t, d_g = 2, d_f = 2, SCALE = 1):
    # assert(abs(t - x) < 1)
    res, d = approx_compare((t-x)/SCALE, d_g=d_g, d_f=d_f) 
    # print(d)
    return (res + 1)/2


