def ref_softmax(x, dim=None):
    # x[x <= -3.4028e+37] = 0
    # print("input shape", x.shape)
    maxes = torch.max(x, dim, keepdim=True)[0]
    x_exp = torch.exp(x-maxes)
    x_exp_sum = torch.sum(x_exp, dim, keepdim=True)
    return x_exp/x_exp_sum

